/** Postgres row types for the V1 schema. Not generated by the Supabase CLI. */

export type UserRole = "admin" | "troop_manager" | "member";
export type TroopStatus = "pending" | "active" | "suspended";
export type SubscriptionStatus = "pending" | "active" | "expired" | "suspended";
export type ListingType = "sale" | "rent" | "exchange" | "wanted";
export type ItemCondition = "new" | "used_good" | "needs_repair";
export type ProductStatus = "active" | "hidden" | "unavailable";
export type ReportReason = "wrong_info" | "inappropriate" | "duplicate" | "other";
export type ReportStatus = "open" | "resolved" | "dismissed";

export type WilayaRow = {
  id: number;
  name_ar: string;
  name_fr: string;
  created_at: string;
  updated_at: string;
};

export type PlanRow = {
  id: string;
  name: string;
  price_dzd: number;
  duration_days: number;
  max_members: number;
  max_products: number;
  is_active: boolean;
  created_at: string;
  updated_at: string;
};

export type TroopRow = {
  id: string;
  name: string;
  wilaya_id: number;
  municipality: string;
  description: string;
  contact_phone: string | null;
  contact_email: string | null;
  status: TroopStatus;
  created_at: string;
  updated_at: string;
};

export type ProfileRow = {
  id: string;
  troop_id: string | null;
  full_name: string;
  phone: string | null;
  role: UserRole;
  is_active: boolean;
  created_at: string;
  updated_at: string;
};

export type SubscriptionRow = {
  id: string;
  troop_id: string;
  plan_id: string;
  price_dzd: number;
  max_members: number;
  max_products: number;
  starts_at: string | null;
  ends_at: string | null;
  status: SubscriptionStatus;
  payment_proof_path: string | null;
  payment_note: string;
  approved_by: string | null;
  approved_at: string | null;
  created_at: string;
  updated_at: string;
};

export type CategoryRow = {
  id: string;
  parent_id: string | null;
  slug: string;
  name_ar: string;
  name_fr: string;
  sort_order: number;
  is_active: boolean;
  created_at: string;
  updated_at: string;
};

export type ProductRow = {
  id: string;
  troop_id: string;
  created_by: string;
  category_id: string;
  title: string;
  description: string;
  listing_type: ListingType;
  condition: ItemCondition;
  price_dzd: number | null;
  rent_price_dzd: number | null;
  wilaya_id: number;
  status: ProductStatus;
  published_at: string | null;
  created_at: string;
  updated_at: string;
};

export type ProductImageRow = {
  id: string;
  product_id: string;
  storage_path: string;
  sort_order: number;
  created_at: string;
  updated_at: string;
};

export type ReportRow = {
  id: string;
  product_id: string;
  reporter_id: string;
  reason: ReportReason;
  details: string;
  status: ReportStatus;
  handled_by: string | null;
  handled_at: string | null;
  created_at: string;
  updated_at: string;
};

export type Database = {
  wilayas: WilayaRow;
  plans: PlanRow;
  troops: TroopRow;
  profiles: ProfileRow;
  subscriptions: SubscriptionRow;
  categories: CategoryRow;
  products: ProductRow;
  product_images: ProductImageRow;
  reports: ReportRow;
};
